class Solution {
public:
    int missingElement(vector<int>& nums, int k) {
        int n = nums.size();
        auto missing = [&](int i) {
            return nums[i] - nums[0] - i;
        };
        if (k > missing(n - 1)) {
            return nums[n - 1] + k - missing(n - 1);
        }
        int left = 0;
        int right = n - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (missing(mid) < k) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return nums[left - 1] + k - missing(left - 1);
    }
};
